  "T'as accès à l'appli complète : programme, nutrition, suivi, road map, tout centralisé au même endroit. 5 formations (environ 25h) arrivent bientôt, pour que tu comprennes ce que tu fais, pas juste que tu le suives.": "You have access to the full app: program, nutrition, tracking, road map, all in one place. 5 courses (about 25 hours) are coming soon, so you understand what you do, not just follow it.",
