  "Décisions pour cette séance": "Decisions for this workout",
  "Rien ici n'est déduit automatiquement, c'est ce que toi tu choisis pour ce client précis, à cette place précise du programme. La classification ci-dessous est une référence générale sur l'exercice ; ça, c'est la mise en œuvre réelle.": "Nothing here is deduced automatically, it's what you choose for this specific client, at this specific spot in the program. The classification below is a general reference for the exercise; this is the real implementation.",
