  "Amplitude visée": "Target range of motion",
  "Ex. Presse à cuisses de sa salle limitée en amplitude basse, ajouter une planche pour compenser.": "E.g. Leg press at their gym limited at the bottom, add a plate to compensate.",
  "Notes sur l'amplitude de mouvement": "Notes on range of motion",
