  "À partir de combien de séries, à quelle intensité, ce mouvement devient inconfortable pour ce client (essoufflement, articulation) au point d'ajuster ?": "After how many sets, at what intensity, does this movement get uncomfortable for this client (breathlessness, joint) enough to adjust?",
