  "Ce que tu choisis ici s'affiche pour tous les clients qui font cet exercice, dans « à prévoir » (programme, logbook, séance en cours). Plusieurs accessoires possibles à la fois.": "What you choose here shows for every client doing this exercise, in \"Planned\" (program, logbook, live workout). Several accessories allowed.",
