  "Chaque pôle peut démarrer à une seule personne, la structure tient même à 1 recrutement près. Clique un pôle ci-dessous pour voir ses postes, et le statut de chaque poste pour le mettre à jour.": "Each department can start with a single person, the structure holds even with just 1 hire. Click a department below to see its roles, and each role's status to update it.",
