  "Objectif du poste": "Role goal",
  "Transformer un message ou un commentaire de quelqu'un d'intéressé en un rendez-vous qualifié dans l'agenda du closer, sans jamais faire perdre de temps au closer avec un lead qui n'ira nulle part.": "Turn a message or comment from an interested person into a qualified meeting in the closer's calendar, without ever wasting the closer's time with a lead going nowhere.",
  "Étapes à maîtriser, dans l'ordre": "Steps to master, in order",
  "Répondre en moins de 2h en journée, avec un message qui relance une vraie conversation (jamais un lien direct en premier message)": "Reply within 2h during the day, with a message that sparks a real conversation (never a direct link as the first message)",
  "Poser 3 questions de qualification : objectif, disponibilité budgétaire approximative, urgence": "Ask 3 qualifying questions: goal, rough budget, urgency",
  "Repérer les signaux d'un lead non qualifié et le laisser partir sans insister": "Spot the signs of an unqualified lead and let it go without pushing",
  "Proposer 2 à 3 créneaux précis, jamais une question ouverte du type \"quand es-tu dispo\"": "Offer 2 to 3 specific slots, never an open question like \"when are you free\"",
  "Confirmer le rendez-vous par écrit et programmer une relance automatique 24h avant": "Confirm the meeting in writing and schedule an automatic reminder 24h before",
  "Mettre à jour la fiche CRM du lead à chaque étape": "Update the lead's CRM record at each step",
  "Exemple de script de qualification": "Example qualification script",
  "Critères de passage en poste rémunéré": "Criteria to get the paid role",
