  "Ce document ne remplace pas un avocat": "This document doesn't replace a lawyer",
  "Les fiches de poste, la trame d'intégration et le déroulé de formation avant embauche ci-dessus sont des points de départ utilisables tels quels. Les contrats de travail, eux, doivent être rédigés ou validés par un avocat en droit du travail avant toute signature, à faire avant le premier recrutement, pas après.": "The role sheets, onboarding outline and pre-hire training above are usable starting points as is. Employment contracts, however, must be drafted or reviewed by an employment lawyer before any signature, to do before the first hire, not after.",
