  "Le lieu d'entraînement de la fiche client filtre déjà le gros du matériel injouable. Ici, affine pour la salle précise de": "The training location in the client profile already filters out most unusable equipment. Here, fine-tune for the specific gym of",
  "et son horaire : une catégorie théoriquement disponible peut être absente de cette salle, ou son poste habituellement pris d'assaut à l'heure d'entraînement habituelle.": "and their schedule: a category that's theoretically available may be missing at this gym, or its station usually crowded at their usual training time.",
  "· écarté pour cette séance": "· excluded for this workout",
  "· disponible": "· available",
  "Rien ici n'empêche d'enregistrer, un point ouvert peut être un choix assumé. C'est un rappel, pas un blocage.": "Nothing here blocks saving, an open point can be a deliberate choice. It's a reminder, not a block.",
  "Diversité des positions de résistance": "Variety of resistance positions",
  "Un groupe travaillé uniquement en position Mi-course, Allongée ou Raccourcie sous-exploite l'hypertrophie par rapport à un mix des 3 (la tension mécanique maximale se déplace selon la longueur du muscle à laquelle il travaille). Un repère, pas une règle bloquante.": "A muscle group trained only in the Mid-range, Lengthened or Shortened position underuses hypertrophy compared to a mix of all 3 (peak mechanical tension shifts with the muscle length it works at). A benchmark, not a blocking rule.",
  ", tous en position": ", all in position",
