  "Notes du coach": "Coach notes",
  "Suivre un mésocycle (montée de volume programmée + décharge en fin de bloc)": "Follow a mesocycle (planned volume ramp + deload at the end of the block)",
  "Le budget de volume ci-dessous (phase Livraison) sert de cible pour l'avant-dernière semaine du bloc : la première semaine démarre plus bas, la dernière est une décharge automatique à ~50%. Un repère de calcul, jamais une réécriture des séries : à toi d'ajuster.": "The volume budget below (Delivery phase) is the target for the second-to-last week of the block: the first week starts lower, the last is an automatic deload at ~50%. A calculation reference, never a rewrite of the sets: up to you to adjust.",
  "Date de départ": "Start date",
  "Date de départ du mésocycle": "Mesocycle start date",
