  "Bloc déjà terminé selon ces dates, il est temps d'en démarrer un nouveau.": "Block already finished according to these dates, time to start a new one.",
  "Séances vides de cette structure": "Empty workouts for this structure",
  "Regénérer les séances vides": "Regenerate empty workouts",
  "Ça pose seulement les séances vides du split choisi, aucun exercice n'est choisi à ta place. Chaque exercice ajouté ensuite passe par sa propre configuration complète (position, amplitude, matériel, risque…), volontairement plus lente qu'un remplissage automatique.": "This only creates the empty workouts for the chosen split, no exercise is chosen for you. Each exercise added afterwards goes through its own full setup (position, range of motion, equipment, risk…), deliberately slower than an automatic fill.",
