  "Repère courant en sèche : perdre environ 0,5 à 1 % du poids de corps par semaine pour garder le muscle. Le posing se travaille toute la prépa, pas seulement les dernières semaines.": "Common cutting benchmark: lose about 0.5 to 1% of body weight per week to keep muscle. Posing is practiced throughout prep, not just the last weeks.",
  "Grossesse et post-partum": "Pregnancy and postpartum",
  "Maternité": "Maternity",
  "Tes séances adaptées, ton périnée et tes signaux à surveiller, semaine après semaine, pendant la grossesse et après l'accouchement. Toujours avec l'accord de ta sage-femme ou de ton médecin.": "Your adapted workouts, pelvic floor and warning signs to watch, week after week, during pregnancy and after giving birth. Always with your midwife's or doctor's approval.",
