  // ── Écrans du quotidien (8) ───────────────────────────────────────────────
  "Le coaching individuel": "One-on-one coaching",
  "Cette page ne concerne que ça : avoir un vrai coach humain, en plus. Tout ce que tu utilises déjà dans l'app (programme, logbook, nutrition, bilan, communauté...) reste gratuit, à vie, que tu réserves un appel ou non.": "This page is only about that: having a real human coach, on top. Everything you already use in the app (program, logbook, nutrition, check-in, community...) stays free, for life, whether you book a call or not.",
  "Ton coaching payant s'est arrêté. Tu gardes l'accès à tous les outils gratuits, pour réactiver le suivi avec ton coach, réserve un nouvel appel ci-dessous.": "Your paid coaching has stopped. You keep access to all the free tools, to restart coaching with your coach, book a new call below.",
  "Aucune obligation, l'appel est gratuit et sans engagement": "No obligation, the call is free and commitment-free",
  "Tu es déjà client EP Coaching": "You're already an EP Coaching client",
  "Tout le contenu est débloqué pour toi.": "All content is unlocked for you.",
  "Prochaine étape": "Next step",
  "Coaching complet pour le moment": "Coaching full for now",
  "Ton coach n'ouvre pas de nouvelle place tout de suite. Rejoins la liste d'attente, il te contactera dès qu'une place se libère.": "Your coach isn't opening new spots right now. Join the waitlist, they'll contact you as soon as a spot opens.",
  "Un appel de 30 min pour voir si le coaching te correspond": "A 30-min call to see if coaching is right for you",
  "Pas de pression. On fait le point sur tes objectifs, tes blocages, et on voit ensemble si l'accompagnement est fait pour toi.": "No pressure. We go over your goals, your blocks, and see together if coaching is right for you.",
  "Réserve ton appel découverte": "Book your discovery call",
  "Ton coach, c'est moi. Pas un algorithme.": "Your coach is me. Not an algorithm.",
  "Je regarde ton programme, ton bilan et ta nutrition chaque semaine. J'ajuste ce qui marche pas. Tu me parles, je te réponds, moi, pas un bot. Aucun plan généré automatiquement.": "I look at your program, check-in and nutrition every week. I adjust what isn't working. You talk to me, I reply, me, not a bot. No auto-generated plan.",
  "Concrètement, ce que ça change au quotidien": "In practice, what it changes day to day",
  "Prêt à arrêter de tâtonner seul ?": "Ready to stop figuring it out alone?",
  "Ta progression dans l'app": "Your progress in the app",
  "Mon agenda": "My calendar",
  "Ton emploi du temps type, semaine après semaine. Ajoute tes créneaux (travail, salle, repas, rendez-vous...), renomme-les et ajuste les horaires comme tu veux. Un modèle par jour peut se répéter sur plusieurs jours d'un coup, et se transformer en rappel push.": "Your typical schedule, week after week. Add your slots (work, gym, meals, appointments...), rename them and adjust the times as you like. A template per day can repeat over several days at once, and turn into a push reminder.",
  "Check-in hebdomadaire": "Weekly check-in",
  "Ton bilan de la semaine": "Your week review",
  "Moy. semaine": "Week avg.",
  "Bilan de ton coach": "Your coach's review",
  "En attente du bilan coach…": "Waiting for the coach's review…",
  "Pour la question entraînement": "For the training question",
  "Ton jour de check-in, c'est le": "Your check-in day is",
  "Reviens ce jour-là pour l'envoyer. Continue de remplir ton bilan quotidien en attendant.": "Come back that day to send it. Keep filling in your daily check-in meanwhile.",
  "Mes bilans": "My check-ins",
  "Mon accompagnement": "My coaching",
  "Ton coach": "Your coach",
  "Envoyer un message": "Send a message",
  "Ce qui est inclus dans ton accompagnement": "What's included in your coaching",
  "Les dernières publications de ton coach": "Your coach's latest posts",
  "Coaching": "Coaching",
  "Choisis ton coach": "Choose your coach",
  "Voici les coachs actifs sur la plateforme. Tu peux aussi contacter Santamaria directement sur Instagram si tu préfères qu'il te suive personnellement.": "Here are the active coaches on the platform. You can also contact Santamaria directly on Instagram if you'd like him to coach you personally.",
  "Contacter Santamaria sur Instagram": "Contact Santamaria on Instagram",
  "Séances, repas notés, bilans, partages : chaque action réelle rapporte des points. Membres gratuits et clients accompagnés, tous coachs confondus, sur un seul classement. Tu peux t'en retirer depuis tes paramètres.": "Workouts, meals logged, check-ins, shares: every real action earns points. Free members and coached clients, all coaches combined, on one leaderboard. You can opt out in your settings.",
  "Tu es masqué du classement : les autres membres ne te voient pas, ta position ici n'est visible que par toi.": "You're hidden from the leaderboard: other members don't see you, your position here is only visible to you.",
  "Tu n'es pas encore classé": "You're not ranked yet",
  "Logue une séance, note un repas ou fais ton bilan du jour : le premier point t'inscrit au classement.": "Log a workout, a meal or your daily check-in: your first point puts you on the leaderboard.",
