  "Ton coach prépare ton programme. En attendant, tu peux déjà loguer une séance libre : tes charges seront gardées pour la suite.": "Your coach is preparing your program. Meanwhile, you can already log a free workout: your loads will be kept for later.",
  "Écrire à mon coach": "Message my coach",
  "Recettes & idées repas": "Recipes & meal ideas",
  "Toutes les recettes triées par régime, phase (surplus, maintenance, sèche), macros, allergènes, saison et goûts, produits français de saison. Ajoute les tiennes ou crée une recette 100% sur mesure.": "All recipes sorted by diet, phase (surplus, maintenance, cut), macros, allergens, season and tastes, French seasonal produce. Add your own or create a fully custom recipe.",
  "La bibliothèque est réservée aux clients accompagnés": "The library is reserved for coached clients",
  "Les guides que je t'envoie restent accessibles par leur lien, et tu continueras à en recevoir. Le catalogue complet, lui, fait partie de l'accompagnement : il est construit pour être utilisé avec un coach qui te dit lequel lire, et quand.": "The guides I send you stay accessible through their link, and you'll keep receiving them. The full catalog, however, is part of the coaching: it's built to be used with a coach who tells you which one to read, and when.",
  "Tout ce que tu as noté cette semaine, en un coup d'œil. Puis 2 minutes de recul pour préparer la suivante.": "Everything you logged this week, at a glance. Then 2 minutes of perspective to prepare the next one.",
  "Impossible de charger ta semaine": "Can't load your week",
