  "Plateforme détectée à l'arrivée, et contenu exact quand le visiteur est passé par le lien suivi d'un script (bouton « Lien suivi du guide » dans Studio créatif, à coller en description ou en bio).": "Platform detected on arrival, and the exact content when the visitor came through a script's tracked link (\"Guide tracked link\" button in Creative studio, to paste in a description or bio).",
