  "Un appel = une ligne. Coche show up et closing une fois l'appel passé, note le CA si signé.": "One call = one row. Check show up and closing once the call is done, enter revenue if signed.",
  "Chaque jour, ton assistant vérifie tes clients : ceux dont le bilan est à l'arrêt reçoivent une relance automatiquement, et tout problème réel trouvé apparaît ici.": "Every day, your assistant checks your clients: those whose check-in has stalled get a nudge automatically, and any real issue found shows up here.",
  "Relance automatique dès qu'un client n'a pas fait son bilan depuis 3 jours, jamais plus d'une fois tous les 3 jours pour le même client.": "Automatic nudge as soon as a client hasn't done their check-in for 3 days, never more than once every 3 days for the same client.",
  "Audit qualité quotidien : programmes laissés inachevés, décrochages réels, jamais un rapport creux, seulement ce qui mérite vraiment ton attention.": "Daily quality audit: unfinished programs, real drop-offs, never an empty report, only what truly deserves your attention.",
  "À vérifier": "To check",
  "Saisis tes campagnes Google/Meta/TikTok Ads et leurs chiffres à jour. Pas de connexion aux régies, juste les métriques qui aident à décider quoi couper ou scaler.": "Enter your Google/Meta/TikTok Ads campaigns and their up-to-date numbers. No connection to the ad platforms, just the metrics that help decide what to cut or scale.",
  "Suivre tes clients, c'est déjà couvert partout ailleurs dans l'appli. Ici, c'est ton propre business de coach : où tu en es, où tu vas, et un système pour y arriver.": "Tracking your clients is already covered everywhere else in the app. Here, it's your own coaching business: where you are, where you're going, and a system to get there.",
  "Tes non-négociables quotidiens, tes objectifs du mois, et les chiffres de la semaine (audience, contenu, leads, ventes).": "Your daily non-negotiables, your goals for the month, and the week's numbers (audience, content, leads, sales).",
