  "Tous les clients": "All clients",
  "Nouveau programme": "New program",
  "Structure d'abord (split, fréquence, objectif de phase), exercices ensuite. Tout ce que tu construis ici est le programme réel de ce client, pas un modèle.": "Structure first (split, frequency, phase goal), exercises next. Everything you build here is this client's real program, not a template.",
  "Rappels & motivation": "Reminders & motivation",
  "Ce client": "This client",
  "n'est pas abonné : la page « Mes tâches » lui affiche un message « réservé aux membres coaching » plutôt que ces tâches, il ne les verra ni les recevra en rappel tant qu'il n'est pas abonné": "isn't subscribed: the \"My tasks\" page shows them a \"coaching members only\" message instead of these tasks, they won't see them or get reminders until they subscribe",
  "Réflexions, conseils, retours d'expérience, visibles par tous les membres.": "Thoughts, advice, lessons learned, visible to all members.",
  "Membres gratuits de la communauté, autonomes, sans suivi coaching. Ils n'apparaissent pas dans tes clients.": "Free community members, on their own, without coaching. They don't appear in your clients.",
  "Mon activité": "My business",
  "Un suivi rapide et déclaratif, pas un logiciel de compta. Exporte en CSV pour ton vrai suivi comptable si besoin.": "A quick, declarative tracker, not accounting software. Export to CSV for your real bookkeeping if needed.",
  "Contraintes & populations spécifiques": "Conditions & specific populations",
  "Blessures, maladies chroniques, handicap, grossesse, ménopause, TCA, véganisme, Ramadan, obésité : comment adapter un programme, et surtout quand orienter vers un professionnel plutôt que d'essayer de gérer la situation seul.": "Injuries, chronic diseases, disability, pregnancy, menopause, eating disorders, veganism, Ramadan, obesity: how to adapt a program, and above all when to refer to a professional instead of handling the situation alone.",
  "Ce contenu est un repère pour construire un programme, jamais un substitut à un avis médical individualisé. Face à un signal d'alerte listé dans une fiche, oriente toujours vers un professionnel de santé avant d'ajuster le programme toi-même.": "This content is a reference for building a program, never a substitute for individual medical advice. When facing a warning sign listed in a record, always refer to a health professional before adjusting the program yourself.",
  "Principes d'adaptation": "Adaptation principles",
  "Signaux d'alerte : orienter vers un professionnel": "Warning signs: refer to a professional",
  "Sources": "Sources",
  "Documents & notes": "Documents & notes",
  "Des modèles à adapter, tes fichiers perso, et un bloc-notes rapide, tout au même endroit.": "Templates to adapt, your personal files, and a quick notepad, all in one place.",
  "Exercices et salles de musculation, dans un seul endroit. Le matériel d'une salle détermine ce qui y est réalisable. Tes membres peuvent aussi enrichir les deux listes.": "Exercises and gyms, in one place. A gym's equipment determines what's doable there. Your members can also grow both lists.",
  "Revenus réels traités par Stripe. Abonnements plateforme des coachs tiers et abonnements directs des clients. Les paiements gérés hors app (lien externe d'un coach, virement) n'y figurent pas.": "Real revenue processed by Stripe. Platform subscriptions of third-party coaches and direct client subscriptions. Payments handled outside the app (a coach's external link, bank transfer) aren't included.",
