  "Mes disponibilités": "My availability",
  "Définis tes créneaux récurrents : tes clients réservent directement un appel 1:1 dans un créneau libre, sans que tu aies à le programmer toi-même. Toutes les heures sont en heure de Paris, et un créneau qui chevauche un live déjà au planning n'est jamais proposé.": "Set your recurring slots: your clients book a 1:1 call directly in a free slot, without you having to schedule it. All times are in Paris time, and a slot overlapping a live already scheduled is never offered.",
