  "Ta newsletter : annonce un contenu, un event, un appel, une relance. Teste-le d'abord sur toi-même pour vérifier le rendu.": "Your newsletter: announce content, an event, a call, a reminder. Test it on yourself first to check how it looks.",
  "Des guides pas à pas pour repartir avec un résultat réel en main, pas juste avoir lu. Suis les étapes dans l'ordre, coche au fur et à mesure.": "Step-by-step guides to walk away with a real result in hand, not just something you read. Follow the steps in order, check them off as you go.",
