  "Aucune alerte, mais pas d'appel live depuis 30 jours ou plus. Rien ne clignote, ça ne veut pas dire qu'il n'y a rien à faire.": "No alert, but no live call for 30 days or more. Nothing is flashing, that doesn't mean there's nothing to do.",
