  "Bibliothèque de modèles": "Template library",
  "Le stock de points de départ réutilisables : modèles de programme, de diète et de road map, indépendants de tout client. La conception au cas par cas, elle, se fait directement dans la fiche du client, où ces modèles sont proposés en point de départ et personnalisables à la volée.": "Your stock of reusable starting points: program, diet and road map templates, independent of any client. Case-by-case design happens directly in the client's profile, where these templates are offered as a starting point and customizable on the fly.",
