  "Base de recettes à partager avec tes clients, triée par régime, phase, macros, allergènes, saison et goûts. Les membres peuvent aussi ajouter les leurs.": "Recipe base to share with your clients, sorted by diet, phase, macros, allergens, season and tastes. Members can add their own too.",
